// Generates per-post briefs, the calendar, the stories plan and the tracker from content/posts.json.
// Usage: node design/build-docs.mjs   (no dependencies)
// Edit content/posts.json, then re-run this and render.mjs. Do not hand-edit generated files.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const data = JSON.parse(readFileSync(join(root, "content/posts.json"), "utf8"));
const { site, campaign } = data.meta;
const slug = (t) => t.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 48);
const day = (iso) => new Date(iso + "T12:00:00Z").toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
const link = (p) => `${site}${p.cta.path}${p.cta.path.includes("?") ? "&" : "?"}utm_source=instagram&utm_medium=social&utm_campaign=${campaign}&utm_content=${p.id}-${p.format}`;
const hook125 = (p) => p.caption.split("\n")[0].length;
const GEN = "<!-- Generated by design/build-docs.mjs from content/posts.json. Edit the JSON, not this file. -->\n";

mkdirSync(join(root, "posts"), { recursive: true });
mkdirSync(join(root, "stories"), { recursive: true });
mkdirSync(join(root, "measurement"), { recursive: true });

for (const p of data.posts) {
  const pil = data.pillars[p.pillar];
  let m = GEN + `# ${p.id.toUpperCase()} · ${day(p.date)} · ${p.time} CET: ${p.title}\n\n`;
  m += `| | |\n|---|---|\n| Phase | ${p.phase} |\n| Pillar | ${pil.name} (${pil.accentName} ${pil.accent}) |\n| Format | ${p.format} |\n| Goal | ${p.goal} |\n| Primary action | ${p.cta.type} |\n| DM keyword | \`${p.cta.dm}\` |\n| Tracked link | ${link(p)} |\n\n`;
  if (p.flag) m += `> **Before posting:** ${p.flag}\n\n`;
  m += `## Hook\n${p.hook}\n\n`;
  if (p.slides) {
    m += `## Slides (${p.slides.length}), 1080×1350\n`;
    p.slides.forEach((s, i) => {
      const f = `../assets/${p.id}/${p.id}-${String(i + 1).padStart(2, "0")}.png`;
      const txt = [s.eyebrow, s.headline, s.stat && `${s.stat} ${s.label}`, s.sub, s.body, s.items && s.items.map((x, j) => `${j + 1}) ${x}`).join(" / "), s.lines && s.lines.join(" / "), s.tag, s.button].filter(Boolean).join(" | ");
      m += `${i + 1}. **${s.kind}**: ${txt}  \n   ![](${f})\n`;
    });
    m += "\n";
  } else if (p.reel) {
    m += `## Reel script (${p.reel.length}), 1080×1920, muted-first\n| Time | Visual | On-screen text | Voiceover |\n|---|---|---|---|\n`;
    p.reel.beats.forEach((b) => (m += `| ${b.t} | ${b.visual} | ${b.onscreen} | ${b.vo} |\n`));
    m += `\n**Audio and delivery:** ${p.reel.audio}  \n**Cover text:** ${p.reel.cover}\n\nReel checklist: original footage, no third-party watermark, audio on, captions burned in, keywords spoken and on screen, keep key text inside the centre safe zone (clear of the top ~250 px and bottom ~340 px). Consider publishing as a Trial Reel first.\n\n`;
  }
  m += `## Caption\nFirst line is ${hook125(p)} characters (shows before "…more", keep it under ~125).\n\n\`\`\`text\n${p.caption}\n\`\`\`\n\n`;
  m += `## First comment (post within 1 minute)\n\`\`\`text\n${p.firstComment}\n\`\`\`\n\n`;
  m += `## Hashtags\n${p.hashtags.join(" ")}  \nPut them at the end of the caption or in the first comment. Keep to 3 to 5.\n\n`;
  m += `## Alt text\n${p.alt}\n\n`;
  m += `## Call to action\n- Primary: ${p.cta.type}. Link in bio points to today's tracked link above (also set the Story link sticker).\n- DM keyword \`${p.cta.dm}\`: reply with the tracked link.\n\n`;
  m += `## Story follow-up (same day)\n${p.story}\n\n`;
  m += `## Facts used and where they come from\n${p.sources.map((s) => `- \`${s}\``).join("\n")}\n`;
  writeFileSync(join(root, "posts", `${p.id}-${slug(p.title)}.md`), m);
}

// Calendar
let cal = GEN + `# 14-day calendar\n\nAll times CET (Zurich). Window: ${day(data.posts[0].date)} to ${day(data.posts.at(-1).date)}.\n\n| Day | Date | Time | Phase | Pillar | Format | Post | Brief |\n|---|---|---|---|---|---|---|---|\n`;
for (const p of data.posts) cal += `| ${p.id.toUpperCase()} | ${day(p.date)} | ${p.time} | ${p.phase} | ${data.pillars[p.pillar].name} | ${p.format} | ${p.title} | [open](posts/${p.id}-${slug(p.title)}.md) |\n`;
const count = (k, v) => data.posts.filter((p) => p[k] === v).length;
cal += `\n**Mix:** ${count("format", "carousel")} carousels, ${count("format", "reel")} Reels, ${count("format", "textcard")} text cards. Pillars: ${Object.keys(data.pillars).map((k) => `${data.pillars[k].name} ${count("pillar", k)}`).join(", ")}.\n`;
writeFileSync(join(root, "calendar.md"), cal);

// Stories
let st = GEN + `# Stories plan\n\nOne Story sequence per feed post, same day, 3 frames: (1) the post teaser or a sticker, (2) the interactive sticker, (3) link sticker with today's tracked link. Stories hold the warm audience and lift early signals on the next feed post. Reply to every sticker response within 24 hours.\n\n`;
for (const p of data.posts) st += `## ${p.id.toUpperCase()} · ${day(p.date)}\n- Frame 1: share the ${p.format} (use "Add to story") with the hook as text.\n- Frame 2: ${p.story}\n- Frame 3: link sticker to ${link(p)}\n\n`;
writeFileSync(join(root, "stories/stories-plan.md"), st);

// Tracker
const rows = ["id,date,time_cet,format,pillar,title,tracked_link,dm_keyword,reach,non_follower_reach_pct,plays_or_views,avg_watch_time_s,likes,comments,saves,sends,profile_visits,follows,link_clicks,site_visits,academy_signups,notes"];
for (const p of data.posts) rows.push([p.id, p.date, p.time, p.format, p.pillar, `"${p.title}"`, link(p), p.cta.dm].join(",") + ",".repeat(14));
writeFileSync(join(root, "measurement/tracker.csv"), rows.join("\n") + "\n");
console.log("built", data.posts.length, "briefs");
